mapper.select:
select count(distinct cientity.id) as ciEntityCount, ci.id as id, ci.name as name, ci.label as label, ci.icon as icon from cmdb_ci ci join cmdb_cientity cientity on ci.id = cientity.ci_id join ( select b.target_id as id from fulltextindex_target_cmdb b join fulltextindex_field_cmdb c on b.target_id = c.target_id join fulltextindex_word d on c.word_id = d.id where b.target_type = 'cientity'
and
d.word like concat(#{item},'%')
and 1 = 0
union select id from cmdb_cientity where id = #{keywordId}
) matched on cientity.id = matched.id group by ci.id
